insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-19', 'admissions', 'ready', '2028 대입 개편 — 정시 축소, 학생부 정성평가 확대', '수능 한 방 역전, 2028부턴 더 좁아진다', '수능 한 방 역전, 2028부터는 점점 어려워져요. 2028학년도 대입은 10명 중 8명을 수시로 뽑고, SKY 정시도 5,105명에서 4,529명으로 줄어요. 정시에서도 학생부를 보는 대학이 늘어나니까, 고1·고2라면 ''진로→과목→세특''을 한 줄로 잇는 연습부터 시작해요. 과목 고를 때 다시 꺼내 보게 저장해 두세요 📌

📌 출처: 대교협 2028 시행계획 · 헤럴드경제 · 베리타스알파 · 메이저맵 트렌드 리포트 (수치는 메이저맵이 재가공)
원문: https://www.heraldk.com/article/2026042919000056717
원문: https://www.veritas-a.com/news/articleView.html?idxno=631785', array['#메이저맵','#고1','#고2','#2028입시','#입시뉴스']::text[], array['/seed/2026-10-19/01.jpg','/seed/2026-10-19/02.jpg','/seed/2026-10-19/03.jpg','/seed/2026-10-19/04.jpg','/seed/2026-10-19/05.jpg','/seed/2026-10-19/06.jpg']::text[], 'report:3fc6af6c-8bcc-816d-a0c6-c44ad8f126aa#4', 'https://www.heraldk.com/article/2026042919000056717', '메이저맵 입시 트렌드 리포트', '{"id": "report:3fc6af6c-8bcc-816d-a0c6-c44ad8f126aa#4", "title": "2028 대입 개편 — 정시 축소, 학생부 정성평가 확대", "track": "admissions", "source_name": "메이저맵 입시 트렌드 리포트", "source_type": "트렌드 리포트", "url": "https://www.heraldk.com/article/2026042919000056717", "published": "2026-10-17", "summary": "2028학년도부터 정시 비중이 줄고 학생부 평가가 정시·교과전형까지 넓어진다. 대상은 고교학점제·내신 5등급제를 처음 겪는 현 고2.", "key_points": ["대상은 현 고2(고교학점제·내신 5등급제 첫 학년). 통합형 수능으로 국어·수학 선택과목이 없어지고 탐구는 통합사회·통합과학으로 바뀐다. 내신 1등급 비율은 4%에서 10%로 넓어진다.", "대교협 2028 시행계획 기준 총 34만8,789명 중 수시가 80.8%(28만1,895명), 정시가 19.2%(6만6,894명, -1,240명)다.", "SKY 정시는 5,105명에서 4,529명으로 11.3% 줄어든다.", "상위15개대 중 8개대가 2028 정시에 학생부를 반영한다.", "SKY 수시 일반전형 중 수능최저 없이 뽑는 비율이 40.1%(2027)에서 57.8%(2028)로 커진다.", "어떤 과목을 골라 어떻게 이수했는지가 평가 요소가 되므로 진로–선택과목–세특의 일관성이 중요해진다."], "check_points": [], "evidence": ["수시 80.8% / 정시 19.2% = 대교협 2028학년도 대입전형 시행계획, 2026-04-30", "SKY 정시 5,105→4,529명(-11.3%) = 헤럴드경제, 2026-04-29", "상위15개대 중 8개대 정시 학생부 반영 = 베리타스알파, 2026-10-17", "내신 1등급 4%→10%, 수능최저 미적용 40.1%→57.8% = 노션 트렌드 리포트 §4, 2026-10-17"], "keywords": ["2028 개편", "학생부 정성평가", "수능최저", "상위15개대"], "next_teaser_hint": ""}'::jsonb, '[{"id": "f1", "value": "80.8%", "claim": "2028학년도 대입에서 수시로 뽑는 비율", "source": "대교협 2028 시행계획", "as_of": "2026-04-30", "url": "https://www.heraldk.com/article/2026042919000056717", "derived_from": ""}, {"id": "f2", "value": "19.2%", "claim": "2028학년도 대입에서 정시로 뽑는 비율", "source": "대교협 2028 시행계획", "as_of": "2026-04-30", "url": "https://www.heraldk.com/article/2026042919000056717", "derived_from": ""}, {"id": "f3", "value": "10명 중 8명", "claim": "수시 80.8%를 쉽게 바꾼 표현", 