insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-20', 'trend', 'ready', '‘L을 가져가’가 대체 무슨 뜻? 요즘 밈 해독해 드림', '''L을 가져가'' 이게 대체 무슨 뜻이야?', '댓글에 ''L 가져가''가 보이면 무슨 뜻일까? 영어 ''Take the L''에서 온 말로, 졌을 땐 쿨하게 인정하자는 뜻이래요. 엄빠 세대 말투를 흉내 내는 ''늙크크 말투'', 슬쩍 자랑하는 댓글 밈까지 한 번에 정리했어요. 밈도 파고들면 언어학·미디어 공부가 된다는 사실! 친구한테 공유해서 같이 알아 두기 📌

📌 출처: 캐릿 (내용은 메이저맵이 학생 눈높이로 재구성)
원문: https://www.careet.net/2008', array['#메이저맵','#요즘밈','#밈해독','#고등학생','#진로탐색']::text[], array['/seed/2026-10-20/01.jpg','/seed/2026-10-20/02.jpg','/seed/2026-10-20/03.jpg','/seed/2026-10-20/04.jpg','/seed/2026-10-20/05.jpg','/seed/2026-10-20/06.jpg']::text[], '3fc6af6c-8bcc-81f2-b4e3-cbba1f0cd34e', 'https://www.careet.net/2008', '캐릿', '{"id": "3fc6af6c-8bcc-81f2-b4e3-cbba1f0cd34e", "title": "‘L을 가져가’가 대체 무슨 뜻? 요즘 밈 해독해 드림", "track": "trend", "source_name": "캐릿", "source_type": "캐릿 아카이브", "url": "https://www.careet.net/2008", "published": "2026-10-15", "summary": "''L을 가져가''는 영어 ''Take the L(패배를 인정해)''에서 온 표현으로 실패·손해 상황에 쓰임", "key_points": ["''L을 가져가''는 영어 ''Take the L(패배를 인정해)''에서 온 표현으로 실패·손해 상황에 쓰임", "''늙크크 말투''는 ''안 봐도 비디오다''처럼 윗세대 말투를 흉내 내는 콘텐츠 유행", "''부라는 게 숨긴다고 숨겨지는 것도 아니고''는 은근한 자랑을 재치 있게 표현하는 댓글 밈", "래퍼 스윙스 칭찬 글에서 파생된 ''멋있는 것 같아... 팬은 ❌'' 밈", "치이카와 캐릭터 관련 밈도 함께 정리"], "check_points": [], "evidence": ["‘L을 가져가’가 대체 무슨 뜻? 요즘 밈 해독해 드림 = 캐릿, 2026-10-15"], "keywords": ["요즘 뜨는 밈", "유행중"], "next_teaser_hint": ""}'::jsonb, '[]'::jsonb, '{"track": "trend", "post_date": "2026-10-20", "topic_id": "3fc6af6c-8bcc-81f2-b4e3-cbba1f0cd34e", "topic_title": "‘L을 가져가’가 대체 무슨 뜻? 요즘 밈 해독해 드림", "kicker": "TUE · 요즘 뭐가 유행?", "next_label": "내일(수) 입시 브리핑", "source": {"name": "캐릿", "date": "2026-10-15", "url": "https://www.careet.net/2008"}, "facts": [], "slides": [{"layout": "hook", "headline": ["''L을 가져가''", "이게 대체", "무슨 뜻이야?"], "highlight_line": 3, "sub": "요즘 댓글창 밈, 뜻 알고 쓰자", "dialogue": [{"who": "polar", "text": "선배, 댓글에 L 가져가래요. 뭐예요?"}, {"who": "may", "text": "…모르고 쓰면 그게 L이야."}], "kicker": "TUE · 요즘 뭐가 유행?", "no": 1}, {"layout": "trend_item", "index": 1, "name": "L을 가져가", "what": "영어 ''Take the L''에서 온 말. 졌으면 쿨하게 인정하라는 뜻", "why": "시험 망친 날, 지각한 날 같은 웃픈 순간을 한마디로 정리해 줘서", "dialogue": [{"who": "polar", "text": "저 오늘 단어 시험… L 가져갈게요."}], "no": 2}, {"layout": "trend_item", "index": 2, "name": "늙크크 말투", "what": "''안 봐도 비디오'' 같은 엄빠 세대 말투를 일부러 흉내 내며 노는 것", "why": "어색하게 따라 할수록 웃기고, 친구랑 같이 쓰면 바로 드립이 돼서", "dialogue": [{"who": "may", "text": "그 말투, 담임쌤도 쓰시던데."}], "no": 3}, {"layout": "trend_item", "index": 3, "name": "숨겨지지 않는 부", "what": "자랑 안 하는 척하면서 슬쩍 자랑할 때 붙이는 댓글 한 줄", "why": "대놓고 하는 자랑보다 덜 얄밉고, 보는 사람도 같이 웃게 돼서", "dialogue": [{"who": "polar", "text": "제 새 필통도 숨겨지지가 않네요?"}], "no": 4}, {"layout": "career", "title": "이 밈, 진로로 이으면?", "links": [{"field": "언어학과", "reason": "말이 생기고 뜻이 바뀌는 과정을 연구해"}, {"field": "미디어커뮤니케이션학과", "reason": "사람들이 왜 이걸 퍼뜨리는지 분석해"}, {"field": "콘텐츠 마케터", "reason": "유행하는 말투로 공감 가는 콘텐츠를 만들어"}], "tip": "메이저맵에서 언어학과 찾아보기", "dialogue": [{"who": "may", "text": "밈도 파고들면 전공이 돼."}], "no": 5}, {"layout": "cta", "headline": "저장해두고 다시 보기", "teaser": "정시인데 수능 점수 안 보는 곳이 있다?", "dialogue": [{"who": "polar", "text": "선배, 내일 것도 기대할게요!"}], "no": 6}], "caption": "댓글에 ''L 가져가''가 보이면 무슨 뜻일까? 영어 ''Take the L''에서 온 말로, 졌을 땐 쿨하게 인정하자는 뜻이래요. 엄빠 세대 말투를 흉내 내는 ''늙크크 말투'', 슬쩍 자랑하는 댓글 밈까지 한 번에 정리했어요. 밈도 파고들면 언어학·미디어 공부가 된다는 사실! 친구한테 공유해서 같이 알아 두기 📌", "hashtags": ["#메이저맵", "#요즘밈", "#밈해독", "#고등학생", "#진로탐색"]}'::jsonb, '{"post_date": "2026-10-20", "track": "trend", "topic_id": "3fc6af6c-8bcc-81f2-b4e3-cbba1f0cd34e", "topic_title": "‘L을 가져가’가 대체 무슨 뜻? 요즘 밈 해독해 드림", "mode": "offline-fixture", "pass": true, "attempts": [{"attempt": 1, "gates": [{"gate": "G1", "pass": true, "violations": [], "warnings": []}, {"gate": "G2", "pass": true, "violations": [], "warnings": [], "max_overlap_ratio": 0.0, "ngram": 6}, {"gate": "G3", "pass": true, "violations": [], "warnings": [], "engine": "code (금칙어·글자 수·구조) — LLM 톤 판정은 1단계"}]}], "g4": {"gate": "G4", "pass": true, "violations": [], "warnings": [], "slides": [{"slide": 1, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["600", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 2, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 3, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 4, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 5, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["600", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 6, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}]}, "steps": [{"step": "소재", "status": "ok", "duration_ms": 0}, {"step": "G1·G2·G3 (시도 1)", "status": "ok", "duration_ms": 0}, {"step": "렌더러+G4", "status": "ok", "duration_ms": 2885}]}'::jsonb, 'seed', 1)
on conflict (post_date) do nothing;

insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-21', 'admissions', 'ready', '[2027정시] 성균관대 1503명(40.7%) ‘축소’.. 다군 사범계열 40명 ‘학생부100% 정성평가’', '정시는 수능? 이제 학생부만 본다', '성균관대 2027학년도 정시에서 사범계열 다군 40명은 수능을 최저기준으로만 보고, 점수는 학생부 100%로 매겨요. 정시 전체 인원도 1,628명에서 1,503명으로 줄었고요. ''정시=수능'' 공식이 조금씩 깨지는 중! 고1·고2라면 지금 수업 기록부터 챙겨 두세요. 저장해두고 다시 보기 📌

📌 출처: 베리타스알파 (수치는 메이저맵이 재가공)
원문: https://www.veritas-a.com/news/articleView.html?idxno=626631', array['#메이저맵','#고1','#고2','#성균관대','#입시뉴스']::text[], array['/seed/2026-10-21/01.jpg','/seed/2026-10-21/02.jpg','/seed/2026-10-21/03.jpg','/seed/2026-10-21/04.jpg','/seed/2026-10-21/05.jpg','/seed/2026-10-21/06.jpg']::text[], '3fc6af6c-8bcc-812b-a8af-d5557d0c7abf', 'https://www.veritas-a.com/news/articleView.html?idxno=626631', '베리타스알파', '{"id": "3fc6af6c-8bcc-812b-a8af-d5557d0c7abf", "title": "[2027정시] 성균관대 1503명(40.7%) ‘축소’.. 다군 사범계열 40명 ‘학생부100% 정성평가’", "track": "admissions", "source_name": "베리타스알파", "source_type": "베리타스 아카이브", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "published": "2026-09-08", "summary": "성균관대 2027 정시 정원내 1503명(40.7%)으로 125명 감소, 다군 사범계열 40명은 수능 점수 없이 학생부100%로 선발", "key_points": ["정원내 1503명(40.7%, 정원외 계약학과 포함)으로 전년 요강 1628명(44.3%)보다 125명 줄었다. 수능위주 1463명은 가군 615명(-71), 나군 673명(-151), 다군 175명(+57)이다.", "교육학·한문교육·수학교육·컴퓨터교육과는 다군에서 각 10명(총 40명)을 학생부100% 정성평가(학업역량 40·탐구역량 40·잠재역량 20%)로 선발한다. 수능은 국수영탐 중 3개 영역 등급합 6 이내의 최저기준으로만 쓴다(전년 나군 수능80%+학생부20%).", "수능위주전형은 모집단위별로 국어·수학(또는 수학·탐구) 중 성적이 높은 영역에 더 큰 비율을 주는 방식으로 바뀌었다. 영어 비중도 10–20%로 모집단위마다 다르고, 의예과는 국30·수30·퀵20·영20으로 고정한다.", "인공지능학과가 다군에 신설(10명)되고 의예과는 가군 16명(+1)이다. 학폭은 1호 100점 감점, 2–9호는 총점 0점 처리한다."], "check_points": ["같은 성대 안에서도 모집단위마다 반영비율이 달라 영역별 강점에 따라 유불리가 갈리므로 모집단위별 환산점수를 꼭 확인해야 한다.", "사범계열 지원자는 학생부 내용과 수능최저 충족이 관건이다."], "evidence": ["[2027정시] 성균관대 1503명(40.7%) ‘축소’.. 다군 사범계열 40명 ‘학생부100% 정성평가’ = 베리타스알파, 2026-09-08"], "keywords": ["상위15개대", "학생부 정성평가", "교대·사범"], "next_teaser_hint": ""}'::jsonb, '[{"id": "f1", "value": "1,503명", "claim": "성균관대 2027 정시 정원내 모집 인원", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f2", "value": "40.7%", "claim": "성균관대 2027 전체 모집 중 정시 비율", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f3", "value": "1,628명", "claim": "성균관대 전년 정시 모집 인원", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f4", "value": "125명", "claim": "정시 모집 인원 감소 폭", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f5", "value": "40명", "claim": "다군 사범계열에서 학생부로만 뽑는 인원", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f6", "value": "100%", "claim": "다군 사범계열 전형에서 학생부 반영 비율", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f7", "value": "10명", "claim": "사범계열 학과별 다군 선발 인원", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f8", "value": "40%", "claim": "학생부 정성평가 중 학업역량 비중", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f9", "value": "40%", "claim": "학생부 정성평가 중 탐구역량 비중", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f10", "value": "20%", "claim": "학생부 정성평가 중 잠재역량 비중", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f11", "value": "등급합 6", "claim": "사범계열 다군 수능 최저기준 (3개 영역)", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f12", "value": "2027", "claim": "이번 요강이 적용되는 학년도", "source": "베리타스알파", "as_of": "2026-09-08", "url": "https://www.veritas-a.com/news/articleView.html?idxno=626631", "derived_from": ""}, {"id": "f13", "value": "수능 80%", "claim": "전년 나