insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-22', 'trend', 'ready', '바이브코딩으로 앱스토어 1위, 나도 가능할까? SNS에서 바이럴된 웹사이트 아이디어 모음', '아이디어만 있으면 앱을 만든다?', '코딩을 잘 몰라도 아이디어 하나로 서비스를 만드는 ''바이브코딩''이 화제예요. 엑스 조회수 4천만 회를 넘긴 일본 ''이미지 튀김'' 사이트, 해 보고 바로 공유하는 테스트·선물형 사이트까지 모아 봤어요. 오늘은 내가 만들고 싶은 앱 이름부터 지어 볼까요? 컴퓨터공학·UX디자인이 궁금하다면 저장해 두기 📌

📌 출처: 캐릿 (내용은 메이저맵이 학생 눈높이로 재구성)
원문: https://www.careet.net/2006', array['#메이저맵','#바이브코딩','#요즘트렌드','#고등학생','#진로탐색']::text[], array['/seed/2026-10-22/01.jpg','/seed/2026-10-22/02.jpg','/seed/2026-10-22/03.jpg','/seed/2026-10-22/04.jpg','/seed/2026-10-22/05.jpg','/seed/2026-10-22/06.jpg']::text[], '3fc6af6c-8bcc-8163-8508-d33361fe29db', 'https://www.careet.net/2006', '캐릿', '{"id": "3fc6af6c-8bcc-8163-8508-d33361fe29db", "title": "바이브코딩으로 앱스토어 1위, 나도 가능할까? SNS에서 바이럴된 웹사이트 아이디어 모음", "track": "trend", "source_name": "캐릿", "source_type": "캐릿 아카이브", "url": "https://www.careet.net/2006", "published": "2026-10-08", "summary": "개인이 아이디어만으로 서비스를 만들어 앱스토어 상위권까지 오르는 ''바이브코딩'' 사례가 늘어나는 흐름", "key_points": ["개인이 아이디어만으로 서비스를 만들어 앱스토어 상위권까지 오르는 ''바이브코딩'' 사례가 늘어나는 흐름", "빈지브라우즈, 플레이 뮤직 띠어리, 메쿠루 등 콘셉트가 뚜렷한 웹사이트 소개", "일본 ''이미지 튀김(画像揚げ)''은 엑스 조회수 4천만 회 이상을 기록하며 바이럴", "번 시디, 브러시 째무, 흔들흔들 쉐이커 스튜디오처럼 아날로그·감성 경험을 웹으로 옮긴 사례", "태국 점성술, 색감 인지 테스트(dialed.gg), 링크 부케 등 테스트·선물형 사이트도 인기"], "check_points": [], "evidence": ["바이브코딩으로 앱스토어 1위, 나도 가능할까? = 캐릿, 2026-10-08"], "keywords": ["일반"], "next_teaser_hint": ""}'::jsonb, '[{"id": "f1", "value": "4천만 회", "claim": "일본 ''이미지 튀김'' 사이트의 엑스 조회수", "source": "캐릿", "as_of": "2026-10-08", "url": "https://www.careet.net/2006", "derived_from": ""}]'::jsonb, '{"track": "trend", "post_date": "2026-10-22", "topic_id": "3fc6af6c-8bcc-8163-8508-d33361fe29db", "topic_title": "바이브코딩으로 앱스토어 1위, 나도 가능할까? SNS에서 바이럴된 웹사이트 아이디어 모음", "kicker": "THU · 요즘 뭐가 유행?", "next_label": "내일(금) 입시 브리핑", "source": {"name": "캐릿", "date": "2026-10-08", "url": "https://www.careet.net/2006"}, "facts": [{"id": "f1", "value": "4천만 회", "claim": "일본 ''이미지 튀김'' 사이트의 엑스 조회수", "source": "캐릿", "as_of": "2026-10-08", "url": "https://www.careet.net/2006", "derived_from": ""}], "slides": [{"layout": "hook", "headline": ["아이디어만", "있으면", "앱을 만든다?"], "highlight_line": 3, "sub": "요즘 뜨는 ''바이브코딩'' 사이트 구경", "dialogue": [{"who": "polar", "text": "선배, 코딩 못해도 앱 만들 수 있어요?"}, {"who": "may", "text": "…요즘은 아이디어가 먼저야."}], "kicker": "THU · 요즘 뭐가 유행?", "no": 1}, {"layout": "trend_item", "index": 1, "name": "바이브코딩", "what": "AI한테 말로 설명하면서 서비스를 같이 만들어 가는 방식", "why": "혼자서도 아이디어 하나로 앱스토어 상위권까지 간 사례가 나와서", "dialogue": [{"who": "polar", "text": "저도 급식 메뉴 앱 만들고 싶어요!"}], "no": 2}, {"layout": "trend_item", "index": 2, "name": "이미지 튀김", "what": "이미지를 ''튀겨'' 준다는 일본 웹사이트. 이름부터 궁금증 폭발", "why": "엑스에서 조회수 {f1}를 넘길 만큼 다들 해 보고 공유해서", "dialogue": [{"who": "may", "text": "단순할수록 더 멀리 퍼져."}], "no": 3}, {"layout": "trend_item", "index": 3, "name": "테스트·선물형 사이트", "what": "색감 테스트, 링크로 주는 꽃다발처럼 해 보고 바로 나누는 사이트", "why": "결과를 친구한테 보내는 순간 같이 노는 놀이가 돼서", "dialogue": [{"who": "polar", "text": "제 색감 점수 친구한테 자랑해야지!"}], "no": 4}, {"layout": "career", "title": "이 유행, 진로로 이으면?", "links": [{"field": "컴퓨터공학과", "reason": "아이디어를 실제로 돌아가는 서비스로 만들어"}, {"field": "UX디자이너", "reason": "사람들이 쓰고 싶게 화면과 경험을 설계해"}, {"field": "디지털콘텐츠학과", "reason": "공유하고 싶은 재미를 기획하고 만들어"}], "tip": "내가 만들고 싶은 앱 이름 지어 보기", "dialogue": [{"who": "may", "text": "코드보다 ''뭘 만들지''가 먼저야."}], "no": 5}, {"layout": "cta", "headline": "저장해두고 다시 보기", "teaser": "수능 앞두고 ''사탐런''이 뭔지 알려줄게", "dialogue": [{"who": "polar", "text": "내일 것도 꼭 볼게요!"}], "no": 6}], "caption": "코딩을 잘 몰라도 아이디어 하나로 서비스를 만드는 ''바이브코딩''이 화제예요. 엑스 조회수 {f1}를 넘긴 일본 ''이미지 튀김'' 사이트, 해 보고 바로 공유하는 테스트·선물형 사이트까지 모아 봤어요. 오늘은 내가 만들고 싶은 앱 이름부터 지어 볼까요? 컴퓨터공학·UX디자인이 궁금하다면 저장해 두기 📌", "hashtags": ["#메이저맵", "#바이브코딩", "#요즘트렌드", "#고등학생", "#진로탐색"]}'::jsonb, '{"post_date": "2026-10-22", "track": "trend", "topic_id": "3fc6af6c-8bcc-8163-8508-d33361fe29db", "topic_title": "바이브코딩으로 앱스토어 1위, 나도 가능할까? SNS에서 바이럴된 웹사이트 아이디어 모음", "mode": "offline-fixture", "pass": true, "attempts": [{"attempt": 1, "gates": [{"gate": "G1", "pass": true, "violations": [], "warnings": []}, {"gate": "G2", "pass": true, "violations": [], "warnings": [], "max_overlap_ratio": 0.0, "ngram": 6}, {"gate": "G3", "pass": true, "violations": [], "warnings": [], "engine": "code (금칙어·글자 수·구조) — LLM 톤 판정은 1단계"}]}], "g4": {"gate": "G4", "pass": true, "violations": [], "warnings": [], "slides": [{"slide": 1, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["600", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 2, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 3, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 4, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 5, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["600", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}, {"slide": 6, "font_scale": 1.0, "overflow": [], "font": {"loaded_weights": ["500", "700", "800", "900"], "check_700": true, "check_900": true}, "pass": true}]}, "steps": [{"step": "소재", "status": "ok", "duration_ms": 0}, {"step": "G1·G2·G3 (시도 1)", "status": "ok", "duration_ms": 0}, {"step": "렌더러+G4", "status": "ok", "duration_ms": 2756}]}'::jsonb, 'seed', 1)
