insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-23', 'admissions', 'ready', '2027 수능 — N수생 급증과 사탐런', '수능 D-한 달, 선배들은 사탐으로 간다', '올해 수능 지원자 10명 중 7명이 사탐만 골랐대요. 과탐만 고른 비율은 22.7%에서 14.2%로 뚝! 졸업생 지원자는 23년 만에 최다! 고1·고2는 2028학년도부터 통합수능이라 이런 과목 눈치싸움은 줄지만, 대신 내신과 학생부가 더 중요해져요. 11월 19일 수능 보는 선배들 응원하면서, 우리는 학생부 한 줄부터 📌

📌 출처: 평가원 접수 결과(머니투데이) · 메이저맵 입시 트렌드 리포트 (수치는 메이저맵이 재가공)
원문: https://www.mt.co.kr/policy/2026/09/08/2026090810102413804', array['#메이저맵','#고1','#고2','#수능','#사탐런']::text[], array['/seed/2026-10-23/01.jpg','/seed/2026-10-23/02.jpg','/seed/2026-10-23/03.jpg','/seed/2026-10-23/04.jpg','/seed/2026-10-23/05.jpg','/seed/2026-10-23/06.jpg']::text[], 'report:3fc6af6c-8bcc-816d-a0c6-c44ad8f126aa#1', 'https://www.mt.co.kr/policy/2026/09/08/2026090810102413804', '메이저맵 입시 트렌드 리포트', '{"id": "report:3fc6af6c-8bcc-816d-a0c6-c44ad8f126aa#1", "title": "2027 수능 — N수생 급증과 사탐런", "track": "admissions", "source_name": "메이저맵 입시 트렌드 리포트", "source_type": "트렌드 리포트", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "published": "2026-10-17", "summary": "현행 수능 마지막 해라 N수생이 23년 만에 최다이고, 사탐만 선택하는 ''사탐런''이 최고조다.", "key_points": ["일정: 수능 2026-11-19, 성적 통지 2026-12-11. 킬러문항 배제·교육과정 내 변별력 기조, EBS 연계 50% 수준.", "지원자 55만1,864명(-2,310명): 재학생 35만5,391명(-1만6,506명)은 줄고, 졸업생 17만3,706명(+1만3,784명, 비율 28.9→31.5%)은 2004학년 이후 23년 만에 최다. 검정고시 2만2,767명.", "왜 몰리나: ① 2028부터 통합수능·내신 5등급제로 바뀌기 전 ''현행 체제 마지막 기회'' ② 지역의사제로 의대 정원 확대 ③ 재수하면 바뀐 제도에 적응해야 하는 부담.", "사탐런: 사탐만 선택 36만7,073명(69.6%, 전년 61.0%)으로 2022 통합수능 도입 이후 최대, 과탐만 선택은 14.2%(전년 22.7%)로 급감. 수학은 확률과통계 64.9%, 미적분 32.4%, 기하 2.7%.", "영향: 자연계의 사탐 유입으로 사탐 상위등급 경쟁이 치열해지고, 과탐은 응시자가 줄어 상대평가 상위등급 인원도 줄어드는 구조 → 수시 수능최저 충족이 최대 변수.", "2028 통합형 수능은 국어·수학 선택과목이 폐지되고 탐구는 통합사회·통합과학으로 바뀐다 (리포트 §4)."], "check_points": [], "evidence": ["사탐만 69.6% / 과탐만 14.2% / 졸업생 17만3,706명 = 머니투데이(평가원 접수 결과), 2026-09-08", "2028 통합수능 = 메이저맵 입시 트렌드 리포트 §4, 2026-10-17"], "keywords": ["트렌드 리포트", "수능", "사탐런 대응"], "next_teaser_hint": ""}'::jsonb, '[{"id": "f1", "value": "69.6%", "claim": "2027 수능 지원자 중 사회탐구만 고른 비율", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f2", "value": "14.2%", "claim": "2027 수능 지원자 중 과학탐구만 고른 비율", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f3", "value": "22.7%", "claim": "전년 수능 과학탐구만 고른 비율", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f4", "value": "61.0%", "claim": "전년 수능 사회탐구만 고른 비율", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f5", "value": "17만3,706명", "claim": "2027 수능 졸업생 지원자 수", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f6", "value": "23년 만에 최다", "claim": "졸업생 지원자 규모가 2004학년 이후 가장 많음", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f7", "value": "11월 19일", "claim": "2027 수능 날짜", "source": "메이저맵 입시 트렌드 리포트", "as_of": "2026-10-17", "url": "", "derived_from": ""}, {"id": "f8", "value": "2028", "claim": "통합형 수능이 처음 적용되는 학년도 (현 고2)", "source": "메이저맵 입시 트렌드 리포트", "as_of": "2026-10-17", "url": "", "derived_from": ""}, {"id": "f9", "value": "10명 중 7명", "claim": "사탐만 선택 69.6%를 쉽게 바꾼 표현", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": "f1"}]'::jsonb, '{"track": "admissions", "post_date": "2026-10-23", "topic_id": "report:3fc6af6c-8bcc-816d-a0c6-c44ad8f126aa#1", "topic_title": "2027 수능 — N수생 급증과 사탐런", "kicker": "FRI · 입시 브리핑", "next_label": "다음 주 월요일 입시 브리핑", "source": {"name": "메이저맵 입시 트렌드 리포트", "date": "2026-10-17", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804"}, "facts": [{"id": "f1", "value": "69.6%", "claim": "2027 수능 지원자 중 사회탐구만 고른 비율", "source": "평가원 접수 결과(머니투데이)", "as_of": "2026-09-08", "url": "https://www.mt.co.kr/policy/2026/09/08/2026090810102413804", "derived_from": ""}, {"id": "f2", "value": "14.2%", "claim": "2027 수능 지원자 중 과학탐구만 고른 